import java.util.Scanner; class Area{double length,breadth;void setDim(double l,double b){length=l;breadth=b;}double getArea(){return length*breadth;}} public class RectangleArea{public static void main(String[]x){Scanner s=new Scanner(System.in);System.out.print("Enter length and breadth: ");double l=s.nextDouble(),b=s.nextDouble();Area a=new Area();a.setDim(l,b);System.out.println("Area = "+a.getArea());s.close();}}